/**
 * File-backed `defineStorage` helper: a file-per-key KV store plus a
 * file-backed `evals` table.
 *
 * Implements the whole `defineStorage` surface with zero external
 * dependencies: the four KV methods against a flat directory of JSON files
 * (one file per key, filename = URI-encoded key), the `cas`
 * group (single-process conditional writes — see the `cas` member below),
 * and eval runs as `eval-runs/<agent>/<runId>.json`. KV keys carry the
 * agent name inside the framework key scheme, but the evals table has no
 * such scheme — the agent subdirectory keeps agents sharing one storage
 * `dir` from mixing or overwriting each other's history. Swap this for a
 * real backend (Postgres, S3, …) in production; the contracts are
 * identical.
 *
 * Layout notes:
 * - KV filenames encode the full key (`encodeURIComponent(key) + ".json"`),
 *   so `list(prefix)` is a readdir + decode + filter, returned in key
 *   order as the contract requires.
 * - `put` writes via tmp + rename: the framework serializes writes, but a
 *   restore-path `get`/`list` can run concurrently and must never see a
 *   torn file.
 * - `get` distinguishes a definitive miss (ENOENT → `undefined`) from a
 *   real failure (anything else throws) — on the lazy-restore path a
 *   throw correctly fails the follow-up instead of forking the session.
 */
import { createHash, randomUUID } from "node:crypto";
import { mkdir, readdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { isAbsolute, join } from "node:path";
import { describeErrorCode } from "../internal/describe-error.js";
import { parseJsonValue } from "../internal/json-value.js";
import { readStoredEvalRun } from "../internal/stored-eval-run.js";
/** File-backed `defineStorage` methods, ready to spread into `defineStorage({...})`. */
/** File `fileKv` writes for one key under `projectRoot`. */
export function fileKvFilePath(projectRoot, key, dir = ".agent-serve/kv") {
    const root = isAbsolute(dir) ? dir : join(projectRoot, dir);
    return join(root, `${encodeURIComponent(key)}.json`);
}
export function fileKv(options) {
    const resolveDir = (ctx) => {
        const dir = options?.dir ?? ".agent-serve/kv";
        return isAbsolute(dir) ? dir : join(ctx.projectRoot, dir);
    };
    // The evals table is scoped per agent (KV keys already carry the agent
    // name via the framework key scheme).
    const evalRunsDir = (ctx) => join(resolveDir(ctx), "eval-runs", encodeURIComponent(ctx.agentName));
    const filePath = (ctx, key) => fileKvFilePath(ctx.projectRoot, key, options?.dir ?? ".agent-serve/kv");
    const readRaw = async (ctx, key) => {
        try {
            return await readFile(filePath(ctx, key), "utf8");
        }
        catch (error) {
            if (describeErrorCode(error) === "ENOENT") {
                return undefined; // definitive miss — key was never written
            }
            throw error; // real failure: let lazy restore fail the follow-up
        }
    };
    const readKey = async (ctx, key) => {
        const text = await readRaw(ctx, key);
        return text === undefined ? undefined : parseJsonValue(text);
    };
    const readVersioned = async (ctx, key) => {
        const text = await readRaw(ctx, key);
        if (text === undefined) {
            return undefined;
        }
        return { value: parseJsonValue(text), version: versionOf(text) };
    };
    // In-process mutex: CAS check-then-write pairs queue on one promise
    // chain so they cannot interleave with each other. Plain `put` stays
    // outside the chain on purpose — it is unconditional LWW and always
    // wins the key, like a SQL upsert would win the row.
    let casChain = Promise.resolve();
    const locked = (task) => {
        const result = casChain.then(task, task);
        casChain = result.then(() => undefined, () => undefined);
        return result;
    };
    return {
        async put(key, value, ctx) {
            await writeJsonAtomic({
                dir: resolveDir(ctx),
                fileName: `${encodeURIComponent(key)}.json`,
                value,
            });
        },
        get(key, ctx) {
            return readKey(ctx, key);
        },
        async delete(key, ctx) {
            await rm(filePath(ctx, key), { force: true });
        },
        async list(prefix, ctx) {
            let names;
            try {
                names = await readdir(resolveDir(ctx));
            }
            catch (error) {
                if (describeErrorCode(error) === "ENOENT") {
                    return []; // nothing stored yet
                }
                throw error;
            }
            const keys = names
                .filter((name) => name.endsWith(".json"))
                .map((name) => decodeURIComponent(name.slice(0, -".json".length)))
                .filter((key) => key.startsWith(prefix))
                .sort();
            const entries = [];
            for (const key of keys) {
                const value = await readKey(ctx, key);
                if (value !== undefined) {
                    entries.push({ key, value });
                }
            }
            return entries;
        },
        // Conditional writes over the same raw value files — no on-disk format
        // change, so data written before the CAS group existed stays readable
        // and plain `put` stays byte-identical. The version token is a content
        // hash of the stored JSON text: it changes whenever the value does,
        // and the in-process mutex makes read-check-write atomic, so a token
        // can never go stale between the check and the rename. The one caveat
        // of hash versions — ABA when a value returns to identical bytes — is
        // moot for coordination values that carry a monotonic counter. CAS
        // correctness is **single-process only**: two pods sharing this
        // directory would race between read and rename, so a file store is
        // only safe for single-instance deployments.
        cas: {
            getWithVersion: (key, ctx) => readVersioned(ctx, key),
            putIfAbsent: (key, value, ctx) => locked(async () => {
                const current = await readVersioned(ctx, key);
                if (current !== undefined) {
                    return { ok: false, current };
                }
                const text = JSON.stringify(value);
                await writeTextAtomic({
                    dir: resolveDir(ctx),
                    fileName: `${encodeURIComponent(key)}.json`,
                    text,
                });
                return { ok: true, version: versionOf(text) };
            }),
            putIfVersion: (key, value, expectedVersion, ctx) => locked(async () => {
                const current = await readVersioned(ctx, key);
                if (current === undefined || current.version !== expectedVersion) {
                    return { ok: false, current };
                }
                const text = JSON.stringify(value);
                await writeTextAtomic({
                    dir: resolveDir(ctx),
                    fileName: `${encodeURIComponent(key)}.json`,
                    text,
                });
                return { ok: true, version: versionOf(text) };
            }),
            async listKeys(prefix, ctx) {
                let names;
                try {
                    names = await readdir(resolveDir(ctx));
                }
                catch (error) {
                    if (describeErrorCode(error) === "ENOENT") {
                        return [];
                    }
                    throw error;
                }
                return names
                    .filter((name) => name.endsWith(".json"))
                    .map((name) => decodeURIComponent(name.slice(0, -".json".length)))
                    .filter((key) => key.startsWith(prefix))
                    .sort();
            },
        },
        // Playground eval batches: one JSON file per run under eval-runs/<agent>/.
        evals: {
            async put(run, ctx) {
                await writeJsonAtomic({
                    dir: evalRunsDir(ctx),
                    fileName: `${encodeURIComponent(run.runId)}.json`,
                    value: run,
                });
            },
            async delete(runId, ctx) {
                await rm(join(evalRunsDir(ctx), `${encodeURIComponent(runId)}.json`), {
                    force: true,
                });
            },
            async list(ctx) {
                const dir = evalRunsDir(ctx);
                let names;
                try {
                    names = await readdir(dir);
                }
                catch (error) {
                    if (describeErrorCode(error) === "ENOENT") {
                        return [];
                    }
                    throw error;
                }
                const runs = [];
                for (const name of names.filter((n) => n.endsWith(".json")).sort()) {
                    // One unreadable/corrupt file must not wipe the whole history:
                    // hydrate treats a throwing list() as "nothing saved".
                    try {
                        const parsed = JSON.parse(await readFile(join(dir, name), "utf8"));
                        const run = readStoredEvalRun(parsed);
                        if (run !== undefined) {
                            runs.push(run);
                        }
                    }
                    catch { }
                }
                return runs;
            },
        },
    };
}
/** Content-hash version token for a stored JSON text. */
function versionOf(text) {
    return `sha256:${createHash("sha256").update(text, "utf8").digest("hex")}`;
}
/** tmp + rename write so concurrent readers never see a torn file. */
async function writeJsonAtomic(args) {
    await writeTextAtomic({
        dir: args.dir,
        fileName: args.fileName,
        text: JSON.stringify(args.value),
    });
}
/** tmp + rename write of exact text (CAS hashes the same bytes it wrote). */
async function writeTextAtomic(args) {
    await mkdir(args.dir, { recursive: true });
    const tmp = join(args.dir, `.tmp-${randomUUID()}`);
    await writeFile(tmp, args.text, "utf8");
    await rename(tmp, join(args.dir, args.fileName));
}
